// GENERATED by tools/bundle-function.mjs. Do not edit; edit supabase/functions/send-reminders/ instead.
import { createClient } from 'npm:@supabase/supabase-js@2.45.4';
import webpush from 'npm:web-push@3.6.7';

// Pure scheduling logic for reminders (no Deno or network APIs, so it is unit-tested with Node).
type Target = {
  user_id: string;
  timezone: string;
  reminder_times: string[];
  due_count: number;
  streak: number;
  streak_last: string | null;
  last_study_day: string | null;
  last_push_at: string | null;
};

const WINDOW_MIN = 15;

function localParts(now: Date, tz: string) {
  const f = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, hour: '2-digit', minute: '2-digit', year: 'numeric', month: '2-digit', day: '2-digit', hour12: false,
  }).formatToParts(now);
  const g = (t: string) => f.find((p) => p.type === t)!.value;
  return { minutes: (+g('hour') % 24) * 60 + +g('minute'), date: `${g('year')}-${g('month')}-${g('day')}` };
}

/** True when the user's local clock is inside [reminder, reminder + WINDOW_MIN). */
function dueNow(now: Date, tz: string, times: string[]) {
  const { minutes } = localParts(now, tz);
  return times.some((t) => {
    const [h, m] = t.split(':').map(Number);
    if (Number.isNaN(h) || Number.isNaN(m)) return false;
    const start = h * 60 + m;
    return minutes >= start && minutes < start + WINDOW_MIN;
  });
}

function message(t: Target, today: string) {
  const studied = t.last_study_day === today;
  const streakAlive = t.streak > 0 && t.streak_last !== today;
  if (t.due_count === 0 && studied) return null; // all done today: stay quiet
  if (t.due_count === 0) {
    return { title: 'Nothing due, but drill anyway 🇫🇷', body: 'Two minutes of Blitz keeps verbs automatic.', url: '#/blitz' };
  }
  const body = streakAlive
    ? `${t.due_count} cards due. Keep your ${t.streak}-day streak alive. 5 minutes is enough.`
    : `${t.due_count} cards are waiting. Verbs don't drill themselves.`;
  return { title: 'Time for your French 🇫🇷', body, url: '#/review' };
}

function shouldSend(t: Target, now: Date) {
  if (!dueNow(now, t.timezone, t.reminder_times)) return null;
  if (t.last_push_at && now.getTime() - new Date(t.last_push_at).getTime() < 10 * 60_000) return null;
  return message(t, localParts(now, t.timezone).date);
}

// Supabase Edge Function: sends Web Push study reminders.
// Called every 15 minutes by pg_cron (see supabase/cron.sql).
// Secrets required:  VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, VAPID_SUBJECT (mailto:you@example.com), APP_URL




const supabase = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
webpush.setVapidDetails(
  Deno.env.get('VAPID_SUBJECT') ?? 'mailto:admin@example.com',
  Deno.env.get('VAPID_PUBLIC_KEY')!,
  Deno.env.get('VAPID_PRIVATE_KEY')!,
);
const APP_URL = Deno.env.get('APP_URL') ?? '/';

Deno.serve(async () => {
  const now = new Date();
  const { data, error } = await supabase.rpc('reminder_targets');
  if (error) return new Response(error.message, { status: 500 });

  let sent = 0, removed = 0;
  for (const t of data as Target[]) {
    try {
      const msg = shouldSend(t, now);
      if (!msg) continue;

      const { data: subs } = await supabase.from('push_subscriptions').select('*').eq('user_id', t.user_id);
      const payload = JSON.stringify({ ...msg, url: APP_URL + msg.url, badge: t.due_count });
      for (const s of subs ?? []) {
        try {
          await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, payload, { TTL: 3600 });
          sent++;
        } catch (e) {
          const code = (e as { statusCode?: number }).statusCode;
          if (code === 404 || code === 410) {
            await supabase.from('push_subscriptions').delete().eq('id', s.id);
            removed++;
          } else console.error('push failed', code, (e as Error).message);
        }
      }
      await supabase.from('user_settings').update({ last_push_at: now.toISOString() }).eq('user_id', t.user_id);
    } catch (e) {
      console.error('target failed', t.user_id, (e as Error).message);
    }
  }
  return Response.json({ checked: data.length, sent, removed });
});
